#include <stdio.h>
int main(void) {
  long sum = 0;
  #pragma omp parallel for reduction(+:sum)
  for (int i = 0; i < 1024; ++i) sum += i;
  printf("%d %ld\n", _OPENMP, sum);
  return sum == (1024L * 1023L / 2) ? 0 : 1;
}

